#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:003','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:003','preserved':True,'artifacts':['user_tasks', 'team_feedback', 'change_notifications', 'gantt_and_usage_reports']})+'\n')
start=time.time(); probes={'solution.py':hashlib.sha256(O.joinpath('solution.py').read_bytes()).hexdigest()}; r={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-dependency-unblock-fe0736601e','source_task_id':'coding:003','event':'optimizer_constraints_completed','event_theme':'partial_then_complete_result','meaning':'A completed availability, dependency, and preference contract replaces provisional priority-only scheduling while preserving tasks, feedback, notifications, and report history.','authority':{'contract': 'team_schedule_optimizer_v2', 'constraints': ['availability', 'task_dependencies', 'no_overlap', 'priority', 'feedback'], 'slot_minutes': 30},'worker_started_at':start,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'independent equivalent authority','workspace_revision_before':None,'workspace_revision_after':probes['solution.py'],'probes':probes}; r['receipt_sha256']=hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest(); O.joinpath('event_receipt.json').write_text(json.dumps(r,sort_keys=True)+'\n')
